import * as fs from 'node:fs';
import * as path from 'node:path';
import { DiscoveredComponent } from './discovery';

/**
 * Generates GlobalComponents interface augmentation for Vue and @vue/runtime-core.
 * This allows Vue-Volar to resolve all auto-discovered Phue components without explicit imports!
 */
export function generateVolarDefinitions(components: DiscoveredComponent[], workspaceRoot: string): string {
  const lines: string[] = [
    '/* eslint-disable */',
    '/* prettier-ignore */',
    '// @ts-nocheck',
    '/**',
    ' * Auto-generated by Phue VS Code Extension.',
    ' * Provides Vue 3 / Volar GlobalComponents registration for Phue autodiscovery.',
    ' * Manual imports in <script> are NOT needed.',
    ' */',
    '',
    "import '@vue/runtime-core';",
    '',
  ];

  const declarations: string[] = [];

  for (const comp of components) {
    let relPath = path.relative(path.join(workspaceRoot, '.phue'), comp.filePath);
    if (!relPath.startsWith('.')) relPath = './' + relPath;
    relPath = relPath.replace(/\\/g, '/');

    // Both PascalCase (PhButton) and kebab-case ('ph-button')
    declarations.push(`    ${comp.pascalName}: typeof import('${relPath}')['default'];`);
    if (comp.kebabName !== comp.pascalName) {
      declarations.push(`    '${comp.kebabName}': typeof import('${relPath}')['default'];`);
    }
  }

  const declBlock = declarations.length > 0 ? declarations.join('\n') : '    // No components discovered yet';

  lines.push("declare module '@vue/runtime-core' {");
  lines.push('  export interface GlobalComponents {');
  lines.push(declBlock);
  lines.push('  }');
  lines.push('}');
  lines.push('');
  lines.push("declare module 'vue' {");
  lines.push('  export interface GlobalComponents {');
  lines.push(declBlock);
  lines.push('  }');
  lines.push('}');
  lines.push('');
  lines.push('export {};');
  lines.push('');

  return lines.join('\n');
}

/**
 * Generates TypeScript shim for *.phue single-file components.
 */
export function generatePhueShims(): string {
  return [
    '/* eslint-disable */',
    '/* prettier-ignore */',
    '// @ts-nocheck',
    'declare module "*.phue" {',
    "  import type { DefineComponent } from 'vue';",
    '  const component: DefineComponent<{}, {}, any>;',
    '  export default component;',
    '}',
    '',
  ].join('\n');
}

/**
 * Writes .phue/phue-components.d.ts and .phue/phue-shims.d.ts into workspace.
 */
export async function writeVolarTypeDefinitions(
  components: DiscoveredComponent[],
  workspaceRoot: string,
): Promise<string> {
  const phueDir = path.join(workspaceRoot, '.phue');
  if (!fs.existsSync(phueDir)) {
    fs.mkdirSync(phueDir, { recursive: true });
  }

  const componentsDtsPath = path.join(phueDir, 'phue-components.d.ts');
  const shimsDtsPath = path.join(phueDir, 'phue-shims.d.ts');

  const content = generateVolarDefinitions(components, workspaceRoot);
  fs.writeFileSync(componentsDtsPath, content, 'utf8');

  if (!fs.existsSync(shimsDtsPath)) {
    fs.writeFileSync(shimsDtsPath, generatePhueShims(), 'utf8');
  }

  return componentsDtsPath;
}

/**
 * Ensures workspace tsconfig.json or jsconfig.json has vueCompilerOptions for .phue
 */
export async function configureWorkspaceForVolar(workspaceRoot: string): Promise<boolean> {
  const tsconfigPath = path.join(workspaceRoot, 'tsconfig.json');
  const jsconfigPath = path.join(workspaceRoot, 'jsconfig.json');

  const targetPath = fs.existsSync(tsconfigPath)
    ? tsconfigPath
    : fs.existsSync(jsconfigPath)
    ? jsconfigPath
    : tsconfigPath;

  let config: Record<string, any> = {};
  if (fs.existsSync(targetPath)) {
    try {
      config = JSON.parse(fs.readFileSync(targetPath, 'utf8'));
    } catch {
      config = {};
    }
  }

  let modified = false;

  // Ensure vueCompilerOptions.extensions includes .phue
  if (!config.vueCompilerOptions) {
    config.vueCompilerOptions = { extensions: ['.vue', '.phue'] };
    modified = true;
  } else {
    const exts = config.vueCompilerOptions.extensions || ['.vue'];
    if (!exts.includes('.phue')) {
      config.vueCompilerOptions.extensions = [...exts, '.phue'];
      modified = true;
    }
  }

  // Ensure include includes .phue and .phue/**/*.d.ts
  if (Array.isArray(config.include)) {
    if (!config.include.includes('**/*.phue')) {
      config.include.push('**/*.phue');
      modified = true;
    }
    if (!config.include.includes('.phue/**/*.d.ts')) {
      config.include.push('.phue/**/*.d.ts');
      modified = true;
    }
  } else if (!config.include) {
    config.include = ['src/**/*', 'App/**/*', '**/*.phue', '.phue/**/*.d.ts'];
    modified = true;
  }

  if (modified) {
    fs.writeFileSync(targetPath, JSON.stringify(config, null, 2), 'utf8');
  }

  return modified;
}
